29	// Fast allocation in a page: just pop from the free list.
30	// Fall back to generic allocation only if the list is empty.
31	// Note: in release mode the (inlined) routine is about 7 instructions with a single test.
32	static mi_decl_forceinline void* mi_page_malloc_zero(mi_theap_t* theap, mi_page_t* page, size_t size, bool zero, mi_page_t** ppage) mi_attr_noexcept
33	{
34	  if (page->block_size != 0) { // not the empty theap
35	    mi_assert_internal(mi_page_block_size(page) >= size);
36	    mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
37	    mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
38	  }
39	
40	  // check the free list
41	  mi_block_t* const block = page->free;
42	  const mi_used_t used = page->used;
43	  #if defined(__GNUC__) 
44	  __asm("" : : : "memory");  // alway load used before the test
45	  #endif  
46	  if (block == NULL) {
47	    return _mi_malloc_generic(theap, size, (zero ? 1 : 0), ppage);
48	  }
49	  mi_assert_internal(block != NULL && _mi_ptr_page(block) == page);
50	  if (ppage != NULL) { *ppage = page; };
51	
52	  // pop from the free list
53	  mi_block_t* next = mi_block_next(page,block);
54	  mi_track_mem_undefined(block,sizeof(*block));
55	  block->next = 0;  // don't leak internal data
56	  page->free = next;
57	  page->used = used+1;
58	  mi_assert_internal(page->free == NULL || _mi_ptr_page(page->free) == page);
59	  mi_assert_internal(page->block_size < MI_MAX_ALIGN_SIZE || _mi_is_aligned(block, MI_MAX_ALIGN_SIZE));
60	
61	  #if MI_DEBUG>3
62	  if (page->free_is_zero && size > sizeof(*block)) {
63	    mi_assert_expensive(mi_mem_is_zero(block+1,size - sizeof(*block)));
64	  }
65	  #endif
66	
67	  // allow use of the block internally
68	  // note: when tracking we need to avoid ever touching the MI_PADDING since
69	  // that is tracked by valgrind etc. as non-accessible (through the red-zone, see `mimalloc/track.h`)
70	  const size_t bsize = mi_page_usable_block_size(page);
71	  mi_track_mem_undefined(block, bsize);
72	
73	  #if (MI_STAT>0)
74	  if (bsize <= MI_LARGE_MAX_OBJ_SIZE) {
75	    mi_theap_stat_increase(theap, malloc_normal, bsize);
76	    #if (MI_STAT>1)
77	    mi_theap_stat_counter_increase(theap, malloc_normal_count, 1);
78	    const size_t bin = _mi_bin(bsize);
79	    mi_theap_stat_increase(theap, malloc_bins[bin], 1);
80	    mi_theap_stat_increase(theap, malloc_requested, size - MI_PADDING_SIZE);
81	    #endif
82	  }
83	  #endif
84	
85	  // zero the block? note: we need to zero the full block size (issue #63)
86	  if mi_likely(!zero) {
87	    // #if MI_SECURE
88	    // block->next = 0;  // don't leak internal data
89	    // #endif
90	    #if (MI_DEBUG>0) && !MI_TRACK_ENABLED && !MI_TSAN
91	      if (!mi_page_is_huge(page)) { memset(block, MI_DEBUG_UNINIT, bsize); }
92	    #endif    
93	  }
94	  else {
95	    if (!page->free_is_zero) {
96	      _mi_memzero_aligned(block, bsize);
97	    }
98	    else {
99	      block->next = 0;
100	      mi_track_mem_defined(block, bsize);
101	    }    
102	  }
103	
104	  #if MI_PADDING // && !MI_TRACK_ENABLED
105	    mi_padding_t* const padding = (mi_padding_t*)((uint8_t*)block + bsize);
106	    ptrdiff_t delta = ((uint8_t*)padding - (uint8_t*)block - (size - MI_PADDING_SIZE));
107	    #if (MI_DEBUG>=2)
108	    mi_assert_internal(delta >= 0 && bsize >= (size - MI_PADDING_SIZE + delta));
109	    #endif
110	    mi_track_mem_defined(padding,sizeof(mi_padding_t));  // note: re-enable since mi_page_usable_block_size may set noaccess
111	    padding->canary = mi_ptr_encode_canary(page,block,page->keys);
112	    padding->delta  = (uint32_t)(delta);
113	    #if MI_PADDING_CHECK_BYTES
114	    if (!mi_page_is_huge(page)) {
115	      uint8_t* fill = (uint8_t*)padding - delta;
116	      const size_t maxpad = (delta > MI_MAX_ALIGN_SIZE ? MI_MAX_ALIGN_SIZE : delta); // set at most N initial padding bytes
117	      for (size_t i = 0; i < maxpad; i++) { fill[i] = MI_DEBUG_PADDING; }
118	    }
119	    #endif
120	  #endif
121	
122	  return block;
123	}
