132	// internal small size allocation
133	static mi_decl_forceinline mi_decl_restrict void* mi_theap_malloc_small_zero_nonnull(mi_theap_t* theap, size_t size, bool zero, mi_page_t** ppage) mi_attr_noexcept
134	{
135	  mi_assert(theap != NULL);
136	  mi_assert(size <= MI_SMALL_SIZE_MAX);
137	  #if MI_DEBUG
138	  mi_assert(mi_theap_matches_thread(theap)); // theaps are thread local
139	  #endif
140	  #if (MI_PADDING || MI_GUARDED)
141	  if mi_unlikely(size == 0) { size = sizeof(void*); }
142	  #endif
143	  #if MI_GUARDED
144	  if mi_unlikely(mi_theap_malloc_use_guarded(theap,size)) {
145	    return _mi_theap_malloc_guarded(theap, size, zero, ppage);
146	  }
147	  #endif
148	
149	  // get page in constant time, and allocate from it
150	  mi_page_t* page = _mi_theap_get_free_small_page(theap, size + MI_PADDING_SIZE);
151	  void* const p = mi_page_malloc_zero(theap, page, size + MI_PADDING_SIZE, zero, ppage);
152	  mi_track_malloc(p,size,zero);
153	
154	  #if MI_DEBUG>3
155	  if (p != NULL && zero) {
156	    mi_assert_expensive(mi_mem_is_zero(p, size));
157	  }
158	  #endif
159	  return p;
160	}
