364	// Expand (or shrink) in place (or fail)
365	void* mi_expand(void* p, size_t newsize) mi_attr_noexcept {
366	  #if MI_PADDING
367	  // we do not shrink/expand with padding enabled
368	  MI_UNUSED(p); MI_UNUSED(newsize);
369	  return NULL;
370	  #else
371	  if (p == NULL) return NULL;
372	  const mi_page_t* const page = mi_validate_ptr_page(p,"mi_expand");  
373	  const size_t size = _mi_page_usable_size(page,p);
374	  if (newsize > size) return NULL;
375	  return p; // it fits
376	  #endif
377	}
