379	static mi_decl_forceinline void* mi_theap_realloc_zero_ex(mi_theap_t* theap, void* p, size_t newsize, bool zero, size_t* pblock_size_pre, size_t* pblock_size_post) mi_attr_noexcept {
380	  // if p == NULL then behave as malloc.
381	  // else if size == 0 then reallocate to a zero-sized block (and don't return NULL, just as mi_malloc(0)).
382	  // (this means that returning NULL always indicates an error, and `p` will not have been freed in that case.)
383	  const mi_page_t* page;
384	  size_t size;
385	  if (p==NULL) {
386	    page = NULL;
387	    size = 0;
388	    if (pblock_size_pre!=NULL) { *pblock_size_pre = 0; }
389	  }
390	  else {    
391	    page = mi_validate_ptr_page(p,"mi_realloc"); 
392	    if mi_unlikely(page==NULL) {  // invalid pointer
393	      if (pblock_size_pre!=NULL) { *pblock_size_pre = 0; }
394	      if (pblock_size_post!=NULL) { *pblock_size_post = 0; }  
395	      return NULL;
396	    } 
397	    size = _mi_page_usable_size(page,p);
398	    if (pblock_size_pre!=NULL) { *pblock_size_pre = mi_page_block_size(page); }
399	  }
400	  // check if we can reuse the existing block
401	  if mi_unlikely(newsize<=size && newsize>=(size/2) && newsize>0) { // note: newsize must be > 0 or otherwise we return NULL for realloc(NULL,0)                 
402	    mi_assert_internal(page!=NULL); // note: page!=NULL (since if p==NULL, we have size=0 and size>=newsize>0
403	    #if MI_THEAP_INITASNULL
404	    if (theap!=NULL)
405	    #endif
406	    {
407	      if (mi_page_heap(page)==_mi_theap_heap(theap)) {  // and within the same heap
408	        mi_assert_internal(p!=NULL);
409	        // todo: do not track as the usable size is still the same in the free; adjust potential padding?
410	        // mi_track_resize(p,size,newsize)
411	        // if (newsize < size) { mi_track_mem_noaccess((uint8_t*)p + newsize, size - newsize); }
412	        if (pblock_size_post!=NULL) { *pblock_size_post = mi_page_block_size(page); }
413	        return p;  // reallocation still fits and not more than 50% waste
414	      }
415	    }
416	  }
417	  // note: we don't zero allocate upfront so we only zero initialize the expanded part 
418	  mi_page_t* newpage; // use block_size for zero-ing, issue #763
419	  void* const newp = _mi_theap_malloc_zero(theap,newsize,false /* no zero */,&newpage);  
420	  if mi_likely(newp != NULL) {
421	    if (pblock_size_post!=NULL) { *pblock_size_post = mi_page_block_size(newpage); }  
422	    const size_t copy_size  = (newsize > size ? size : newsize);
423	    const size_t zero_start = _mi_align_down( (copy_size >= sizeof(intptr_t) ? copy_size - sizeof(intptr_t) : 0), sizeof(intptr_t)); // also set last word in the previous allocation to zero to ensure any padding is zero-initialized
424	    const size_t usable = _mi_page_usable_size(newpage,newp); 
425	    mi_assert_internal(usable >= newsize);     
426	    if (zero && usable > zero_start) {      
427	      _mi_memzero_aligned((uint8_t*)newp + zero_start, usable - zero_start);
428	    }
429	    else if (newsize == 0) {
430	      ((uint8_t*)newp)[0] = 0; // work around for applications that expect zero-reallocation to be zero initialized (issue #725)
431	    }
432	    if mi_likely(p != NULL) {
433	      mi_track_mem_defined(p,copy_size);  // _mi_useable_size may be too large for byte precise memory tracking..
434	      _mi_memcpy_aligned(newp, p, copy_size);
435	      mi_free(p); // only free the original pointer if successful
436	    }
437	  }
438	  return newp;
439	}
