586	mi_decl_nodiscard static mi_decl_restrict char* mi_theap_realpath(mi_theap_t* theap, const char* fname, char* resolved_name) mi_attr_noexcept {
587	  // todo: use GetFullPathNameW to allow longer file names
588	  if (fname==NULL || *fname==0) {
