602	      case ERROR_PATH_NOT_FOUND:    errno = ENOTDIR; break;
603	      case ERROR_FILE_NOT_FOUND:    errno = ENOENT; break;
604	      case ERROR_NOT_ENOUGH_MEMORY: errno = ENOMEM; break;
605	      default:                      errno = EIO;
