625	static size_t mi_path_max(void) {
626	  static _Atomic(size_t) path_max = 0;
627	  size_t pmax = mi_atomic_load_acquire(&path_max);
628	  if (pmax == 0) {
629	    long m = 0;
630	    #ifdef _PC_PATH_MAX
631	    m = pathconf("/",_PC_PATH_MAX);
632	    #endif
633	    if (m <= 0) pmax = 4096;      // guess
634	    else if (m < 256) pmax = 256; // at least 256
635	    else if (m > 64*1024) pmax = 64*1024;  // at most 64 KiB
636	    else pmax = m;
637	    size_t expected = 0;
638	    mi_atomic_cas_strong_acq_rel(&path_max, &expected, pmax);
