863	#if MI_GUARDED
864	// We always allocate a guarded allocation at an offset (`mi_page_has_interior_pointers` will be true).
865	// We then set the first word of the block to `0` for regular offset aligned allocations (in `alloc-aligned.c`)
866	// and the first word to `~0` for guarded allocations to have a correct `mi_usable_size`
867	
868	static void* mi_block_ptr_set_guarded(mi_block_t* block, size_t obj_size, size_t* usable_size) {
869	  // todo: we can still make padding work by moving it out of the guard page area
870	  mi_page_t* const page = _mi_ptr_page(block);
871	  mi_page_set_has_interior_pointers(page, true);
872	  block->next = MI_BLOCK_TAG_GUARDED;
873	
874	  // set guard page at the end of the block
875	  const size_t block_size = mi_page_block_size(page);  // must use `block_size` to match `mi_free_local`
876	  const size_t os_page_size = _mi_os_page_size();
877	  mi_assert_internal(block_size >= obj_size + os_page_size + sizeof(mi_block_t));
878	  if (block_size < obj_size + os_page_size + sizeof(mi_block_t)) {
879	    // should never happen
880	    mi_free(block);
881	    return NULL;
882	  }
883	  uint8_t* guard_page = (uint8_t*)block + block_size - os_page_size;
884	  // note: the alignment of the guard page relies on blocks being os_page_size aligned which
885	  // is ensured in `mi_arena_page_alloc_fresh`.  
886	  mi_assert_internal(_mi_is_aligned(block, os_page_size));
887	  mi_assert_internal(_mi_is_aligned(guard_page, os_page_size));
888	  if (!page->memid.is_pinned && _mi_is_aligned(guard_page, os_page_size)) {
889	    const bool ok = _mi_os_protect(guard_page, os_page_size);
890	    if mi_unlikely(!ok) {
891	      _mi_warning_message("failed to set a guard page behind an object (object %p of size %zu)\n", block, block_size);
892	    }
893	  }
894	  else {
895	    _mi_warning_message("unable to set a guard page behind an object due to pinned memory (large OS pages?) (object %p of size %zu)\n", block, block_size);
896	  }
897	
898	  // align pointer just in front of the guard page
899	  size_t offset = block_size - os_page_size - obj_size;
900	  mi_assert_internal(offset > sizeof(mi_block_t));
901	  if (offset > MI_PAGE_MAX_OVERALLOC_ALIGN) {
902	    // give up to place it right in front of the guard page if the offset is too large for unalignment
903	    offset = MI_PAGE_MAX_OVERALLOC_ALIGN;
904	  }
905	  uint8_t* const p = (uint8_t*)block + offset;
906	  mi_assert_internal(p == guard_page - obj_size || offset >= MI_PAGE_MAX_OVERALLOC_ALIGN);
907	  if (usable_size != NULL) { *usable_size = (guard_page - p); mi_assert_internal(mi_usable_size(p)==*usable_size); }
908	  mi_track_align(block, p, offset, obj_size);
909	  mi_track_mem_defined(block, sizeof(mi_block_t));
910	  return p;
911	}
912	
913	mi_decl_restrict void* _mi_theap_malloc_guarded(mi_theap_t* theap, size_t size, bool zero, mi_page_t** ppage) mi_attr_noexcept
914	{
915	  // allocate multiple of page size ending in a guard page
916	  // ensure minimal alignment requirement?
917	  if mi_unlikely(size >= MI_MAX_ALLOC_SIZE - MI_PADDING_SIZE) {  // check up front so the `req_size` won't overflow    
918	    _mi_error_message(EOVERFLOW, "(guarded) allocation request is too large (%zu bytes)\n", size);
919	    return NULL;
920	  }
921	  const size_t os_page_size = _mi_os_page_size();
922	  const size_t obj_size = (mi_option_is_enabled(mi_option_guarded_precise) ? size : _mi_align_up(size, MI_MAX_ALIGN_SIZE));
923	  const size_t bsize    = _mi_align_up(_mi_align_up(obj_size, MI_MAX_ALIGN_SIZE) + sizeof(mi_block_t), MI_MAX_ALIGN_SIZE);
924	  const size_t req_size = _mi_align_up(bsize + os_page_size, os_page_size);  
925	  mi_block_t* const block = (mi_block_t*)_mi_malloc_generic(theap, req_size, 0 /* don't zero */, ppage);
926	  if (block==NULL) return NULL;
927	  size_t usable_size = 0;
928	  void* const p = mi_block_ptr_set_guarded(block, obj_size, &usable_size);
929	  if (p == NULL) return NULL;
930	  if (zero) {
931	    _mi_memzero(p,obj_size);  // we have to zero afterwards as padding might have written inside the block (if the `blocksize > reqsize + os_page_size`)
932	  }
933	
934	  // stats
935	  mi_track_malloc(p, usable_size, zero);    
936	  if (!mi_theap_is_initialized(theap)) { theap = _mi_theap_default(); }
937	  mi_theap_stat_counter_increase(theap, malloc_guarded_count, 1);
938	  #if MI_STAT>1
939	  // adjust stats to only count the allocated size of the block (and not the guard page)
940	  mi_theap_stat_adjust_decrease(theap, malloc_requested, req_size);
941	  mi_theap_stat_increase(theap, malloc_requested, size);
942	  #endif
943	  #if MI_DEBUG>3
944	  if (zero) {
945	    mi_assert_expensive(mi_mem_is_zero(p, size));
946	  }
947	  #endif
948	  return p;
949	}
950	#endif
951	
952	// ------------------------------------------------------
953	// ensure explicit external inline definitions are emitted!
954	// ------------------------------------------------------
955	
956	#ifdef __cplusplus
957	void* _mi_externs[] = {
958	  (void*)&_mi_page_malloc_zero,
959	  (void*)&_mi_theap_malloc_zero,
960	  (void*)&_mi_theap_malloc_zero_ex,
961	  (void*)&mi_theap_malloc,
962	  (void*)&mi_theap_zalloc,
963	  (void*)&mi_theap_malloc_small,
964	  (void*)&mi_theap_zalloc_small,
965	  (void*)&mi_theap_calloc,
