343	// Get a fresh page to use
344	static mi_page_t* mi_page_fresh(mi_theap_t* theap, mi_page_queue_t* pq) {
345	  mi_assert_internal(mi_theap_contains_queue(theap, pq));
346	  mi_page_t* page = mi_page_fresh_alloc(theap, pq, pq->block_size, 0);
347	  if (page==NULL) return NULL;
348	  mi_assert_internal(pq->block_size==mi_page_block_size(page));
349	  mi_assert_internal(pq==mi_theap_page_queue_of(theap, page));
350	  return page;
351	}
