762	  Find pages with free blocks
763	-------------------------------------------------------------*/
764	
765	// Find a page with free blocks of `page->block_size`.
766	static mi_decl_noinline mi_page_t* mi_page_queue_find_free_ex(mi_theap_t* theap, mi_page_queue_t* pq, bool first_try)
767	{
768	  // search through the pages in "next fit" order
769	  size_t count = 0;
770	  long candidate_limit = 0;          // we reset this on the first candidate to limit the search
771	  long page_full_retain = (pq->block_size > MI_SMALL_MAX_OBJ_SIZE ? 0 : theap->page_full_retain); // only retain small pages
772	  mi_page_t* page_candidate = NULL;  // a page with free space
773	  mi_page_t* page = pq->first;
774	
775	  while (page != NULL)
776	  {
777	    mi_page_t* next = page->next; // remember next (as this page can move to another queue)
778	    count++;
779	    candidate_limit--;
780	
781	    // search up to N pages for a best candidate
782	
783	    // is the local free list non-empty?
784	    bool immediate_available = mi_page_immediate_available(page);
785	    if (!immediate_available) {
786	      // collect freed blocks by us and other threads to we get a proper use count
787	      _mi_page_free_collect(page, false);
788	      immediate_available = mi_page_immediate_available(page);
789	    }
790	
791	    // if the page is completely full, move it to the `mi_pages_full`
792	    // queue so we don't visit long-lived pages too often.
793	    if (!immediate_available && !mi_page_is_expandable(page)) {
794	      page_full_retain--;
795	      if (page_full_retain < 0) {
796	        mi_assert_internal(!mi_page_is_in_full(page) && !mi_page_immediate_available(page));
797	        mi_page_to_full(page, pq);
798	      }
799	    }
800	    else {
801	      // the page has free space, make it a candidate
802	      // we prefer non-expandable pages with high usage as candidates (to reduce commit, and increase chances of free-ing up pages)
803	      if (page_candidate == NULL) {
804	        page_candidate = page;
805	        candidate_limit = _mi_option_get_fast(mi_option_page_max_candidates);
806	      }
807	      else if (mi_page_all_free(page_candidate)) {
808	        _mi_page_free(page_candidate, pq);
809	        page_candidate = page;
810	      }
811	      // prefer to reuse fuller pages (in the hope the less used page gets freed)
812	      else if (page->used >= page_candidate->used && !mi_page_is_mostly_used(page)) { // && !mi_page_is_expandable(page)) {
813	        page_candidate = page;
814	      }
815	      // if we find a non-expandable candidate, or searched for N pages, return with the best candidate
816	      if (immediate_available || candidate_limit <= 0) {
817	        mi_assert_internal(page_candidate!=NULL);
818	        break;
819	      }
820	    }
821	
822	  #if 0
823	    // first-fit algorithm without candidates
824	    // If the page contains free blocks, we are done
825	    if (mi_page_immediate_available(page) || mi_page_is_expandable(page)) {
826	      break;  // pick this one
827	    }
828	
829	    // If the page is completely full, move it to the `mi_pages_full`
830	    // queue so we don't visit long-lived pages too often.
831	    mi_assert_internal(!mi_page_is_in_full(page) && !mi_page_immediate_available(page));
832	    mi_page_to_full(page, pq);
833	  #endif
834	
835	    page = next;
836	  } // for each page
837	
838	  mi_theap_stat_counter_increase(theap, page_searches, count);
839	  mi_theap_stat_counter_increase(theap, page_searches_count, 1);
840	
841	  // set the page to the best candidate
842	  if (page_candidate != NULL) {
843	    page = page_candidate;
844	  }
845	  if (page != NULL) {
846	    if (!mi_page_immediate_available(page)) {
847	      mi_assert_internal(mi_page_is_expandable(page));
848	      if (!mi_page_extend_free(theap, page)) {
849	        page = NULL; // failed to extend
850	      }
851	    }
852	    mi_assert_internal(page == NULL || mi_page_immediate_available(page));
853	  }
854	
855	  if (page == NULL) {
856	    _mi_theap_collect_retired(theap, false); // perhaps make a page available
857	    page = mi_page_fresh(theap, pq);         
858	    mi_assert_internal(page == NULL || mi_page_immediate_available(page));
859	    if (page == NULL && first_try) {
860	      // out-of-memory _or_ an abandoned page with free blocks was reclaimed, try once again
861	      page = mi_page_queue_find_free_ex(theap, pq, false);
862	      mi_assert_internal(page == NULL || mi_page_immediate_available(page));
863	    }
864	  }
865	  else {
866	    mi_assert_internal(page == NULL || mi_page_immediate_available(page));
867	    // move the page to the front of the queue
868	    mi_page_queue_move_to_front(theap, pq, page);
869	    page->retire_expire = 0;
870	    // _mi_theap_collect_retired(theap, false); // update retire counts; note: increases rss on MemoryLoad bench so don't do this
871	  }
872	  mi_assert_internal(page == NULL || mi_page_immediate_available(page));
873	
874	
875	  return page;
876	}
