903	// Find a page with free blocks of `size`.
904	static inline mi_page_t* mi_page_queue_find_free(mi_theap_t* theap, mi_page_queue_t* pq) {
905	  // mi_page_queue_t* pq = mi_page_queue(theap, size);
906	  mi_assert_internal(!mi_page_queue_is_huge(pq));
907	
908	  // check the first page: we even do this with candidate search or otherwise we re-search every time
909	  mi_page_t* page = mi_page_queue_lookup_free_first(theap,pq);
910	  if (page==NULL) {
911	    page = mi_page_queue_find_free_ex(theap, pq, true);
912	    if (page==NULL) return NULL;
913	  }  
914	  mi_assert_internal(mi_page_immediate_available(page));
915	  mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
916	  mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
917	  return page;
918	}
