920	// Huge pages contain just one block, and the segment contains just that page.
921	// Huge pages are also use if the requested alignment is very large (> MI_BLOCK_ALIGNMENT_MAX)
922	// so their size is not always `> MI_LARGE_OBJ_SIZE_MAX`.
923	static mi_page_t* mi_huge_page_alloc(mi_theap_t* theap, size_t size, size_t page_alignment, mi_page_queue_t* pq) {
924	  const size_t block_size = _mi_os_good_alloc_size(size);
925	  // mi_assert_internal(mi_bin(block_size) == MI_BIN_HUGE || page_alignment > 0);
926	  #if MI_HUGE_PAGE_ABANDON
927	  #error todo.
928	  #else
929	  // mi_page_queue_t* pq = mi_page_queue(theap, MI_LARGE_MAX_OBJ_SIZE+1);  // always in the huge queue regardless of the block size
930	  mi_assert_internal(mi_page_queue_is_huge(pq));
931	  #endif
932	  mi_page_t* page = mi_page_fresh_alloc(theap, pq, block_size, page_alignment);
933	  if (page != NULL) {
934	    mi_assert_internal(mi_page_block_size(page) >= size);
935	    mi_assert_internal(mi_page_immediate_available(page));
936	    mi_assert_internal(mi_page_is_huge(page));
937	    mi_assert_internal(mi_page_is_singleton(page));
938	    #if MI_HUGE_PAGE_ABANDON
939	    mi_assert_internal(mi_page_is_abandoned(page));
940	    mi_page_set_theap(page, NULL);
941	    #endif
942	    mi_theap_stat_increase(theap, malloc_huge, mi_page_block_size(page));
943	    mi_theap_stat_counter_increase(theap, malloc_huge_count, 1);
944	  }
945	  return page;
946	}
