948	// Allocate a page
949	// Note: in debug mode the size includes MI_PADDING_SIZE and might have overflowed.
950	static mi_page_t* mi_find_page(mi_theap_t* theap, size_t size, size_t huge_alignment) mi_attr_noexcept {
951	  const size_t req_size = size - MI_PADDING_SIZE;  // correct for padding_size in case of an overflow on `size`
952	  if mi_unlikely(req_size > MI_MAX_ALLOC_SIZE) {
953	    _mi_error_message(EOVERFLOW, "allocation request is too large (%zu bytes)\n", req_size);
954	    return NULL;
955	  }
956	  mi_page_queue_t* pq = mi_page_queue(theap, (huge_alignment > 0 ? MI_LARGE_MAX_OBJ_SIZE+1 : size));
957	  mi_page_t* page;
958	  // huge allocation?
959	  if mi_unlikely(mi_page_queue_is_huge(pq) || req_size > MI_MAX_ALLOC_SIZE) {
960	    page = mi_huge_page_alloc(theap,size,huge_alignment,pq);
961	  }
962	  else {
963	    // otherwise find a page with free blocks in our size segregated queues
964	    #if MI_PADDING
965	    mi_assert_internal(size >= MI_PADDING_SIZE);
966	    #endif
967	    page = mi_page_queue_find_free(theap,pq);
968	  }
969	  if (page==NULL) return NULL;
970	  mi_assert_internal(mi_page_block_size(page) >= size);
971	  mi_assert_internal(mi_page_immediate_available(page));
972	  mi_assert_internal(_mi_is_aligned(mi_page_slice_start(page), MI_PAGE_ALIGN));
973	  mi_assert_internal(_mi_ptr_page(mi_page_start(page))==page);
974	  return page;
975	}
