35	/* -----------------------------------------------------------
36	  Queue query
37	----------------------------------------------------------- */
38	
39	
40	static inline bool mi_page_queue_is_huge(const mi_page_queue_t* pq) {
41	  return (pq->block_size == (MI_LARGE_MAX_OBJ_SIZE+sizeof(uintptr_t)));
42	}
43	
44	static inline bool mi_page_queue_is_full(const mi_page_queue_t* pq) {
45	  return (pq->block_size == (MI_LARGE_MAX_OBJ_SIZE+(2*sizeof(uintptr_t))));
46	}
47	
48	static inline bool mi_page_queue_is_special(const mi_page_queue_t* pq) {
49	  return (pq->block_size > MI_LARGE_MAX_OBJ_SIZE);
50	}
51	
52	static inline size_t mi_page_queue_count(const mi_page_queue_t* pq) {
53	  return pq->count;
54	}
